/**
 * History tracker (persisted activity log) + manual late-cutoff trigger —
 * split out of server.js (2026-07-21). Dashboard's "History tracker" card.
 * Read for anyone signed in; deletes (single or clear-all) reuse
 * manageDelegates, same as the activity these entries come from (delegate
 * add/edit/delete).
 */
import { Router } from "express";
import { wrap } from "../../lib/wrap.js";
import { actorOf } from "../../lib/actor.js";
import { requireAuth, requirePermission } from "../../lib/auth.js";
import { guardTrip } from "../../lib/tripAccess.js";
import { getActivity, deleteActivity, deleteAllActivity, rollbackActivity, applyLateCutoff, resolveTripUuid, getVisibleCoachIds } from "../../data.js";

const router = Router();

// ?tripId= scopes to one trip's own activity (2026-07-24 — was always
// global). Omit, or "t-1", for the old "every trip mixed together" view.
router.get("/api/activity", requireAuth(), wrap(async (req, res) => {
  const limit = Math.min(Number(req.query.limit) || 200, 1000);
  const tripUuid = await resolveTripUuid(req.query.tripId);
  // Per-trip authorisation (2026-08-05). A non-admin must name a trip they're
  // actually on: the coach filter below narrows WHICH entries they see, but it
  // can't stop them asking for another trip's log — and with no tripId at all
  // it returned every trip mixed together. guardTrip() fails closed on a null
  // trip, so "all trips" stays admin-only. See lib/tripAccess.js, AI Log 262.
  if (req.account?.role !== "admin" && !(await guardTrip(req, res, tripUuid))) return;
  const visibleCoachIds = await getVisibleCoachIds(tripUuid, req.account);
  let activity = await getActivity(limit, tripUuid);
  // Coach-scoped staff (2026-07-27 — see getVisibleCoachIds' doc) only sees
  // History Log entries for delegates on a coach they can see; entries with
  // no resolvable coach (a deleted delegate, a trip-level event) still show,
  // since they aren't clearly someone else's territory.
  if (visibleCoachIds) activity = activity.filter((a) => !a.coachId || visibleCoachIds.has(a.coachId));
  res.json({ activity });
}));

router.delete("/api/activity/:id", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const ok = await deleteActivity(req.params.id);
  if (!ok) return res.status(404).json({ error: "NOT_FOUND" });
  res.json({ deleted: true });
}));

// Scoped to ?tripId= when given, so "Clear all" while viewing one trip's
// history doesn't silently wipe every other trip's too.
router.delete("/api/activity", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const tripUuid = await resolveTripUuid(req.query.tripId);
  const deleted = await deleteAllActivity(tripUuid);
  res.json({ deleted });
}));

// Field-level rollback for one History Log entry — see rollbackActivity()
// in data.js for what "rollbackable" means (delegate-edit entries only,
// not add/remove) and its documented limitations.
router.post("/api/activity/:id/rollback", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const result = await rollbackActivity(req.params.id, actorOf(req));
  if (result.error === "NOT_FOUND") return res.status(404).json({ error: "NOT_FOUND", message: "That history entry no longer exists." });
  if (result.error === "NOT_ROLLBACKABLE") return res.status(400).json({ error: "NOT_ROLLBACKABLE", message: "This entry can't be rolled back." });
  if (result.error === "DELEGATE_GONE") return res.status(404).json({ error: "DELEGATE_GONE", message: "That delegate no longer exists." });
  res.json(result.delegate);
}));

// Manual trigger for the Late-status cutoff check (see applyLateCutoff() in
// data.js + the background interval in server.js that normally runs it
// automatically every minute). Exists for two reasons: (1) so a manual
// re-check is possible if the interval was ever down, and (2) so this can
// actually be tested/demoed without waiting for real wall-clock 10:00 AM —
// `force: true` bypasses the hour check entirely (still only ever touches
// ASSIGNED delegates either way).
router.post("/api/system/late-cutoff", requirePermission("manageDelegates"), wrap(async (req, res) => {
  const result = await applyLateCutoff(req.body?.force ? new Date(2000, 0, 1, 23, 59) : undefined);
  res.json(result);
}));

export default router;
